@@ -6780,15 +6780,0 @@
-// shift left by shamt and add (unsigned word variant)
-// Rd = (zext32(Rs1) << shamt) + Rs2
-// emits sh1add_uw/sh2add_uw/sh3add_uw for shamt 1/2/3
-void MacroAssembler::shadd_uw(Register Rd, Register Rs1, Register Rs2, int shamt) {
-  assert(UseZba, "shadd_uw requires Zba");
-  assert(1 <= shamt && shamt <= 3, "shamt is invalid");
-  if (shamt == 1) {
-    sh1add_uw(Rd, Rs1, Rs2);
-  } else if (shamt == 2) {
-    sh2add_uw(Rd, Rs1, Rs2);
-  } else {
-    sh3add_uw(Rd, Rs1, Rs2);
-  }
-}
-

@@ -387,17 +387,0 @@
-instruct shaddL_reg_reg_and_uxtw_b(iRegLNoSp dst, iRegL src1, iRegL src2, immL_32bits mask, immIScale imm) %{
-  predicate(UseZba);
-  match(Set dst (AddL src1 (LShiftL (AndL src2 mask) imm)));
-
-  ins_cost(ALU_COST);
-  format %{ "shadd.uw $dst, $src2, $src1, $imm\t#@shaddL_reg_reg_and_uxtw_b" %}
-
-  ins_encode %{
-    __ shadd_uw(as_Register($dst$$reg),
-                as_Register($src2$$reg),
-                as_Register($src1$$reg),
-                $imm$$constant);
-  %}
-
-  ins_pipe(ialu_reg_reg);
-%}
-

